--
-- Table structure for table `ratings`
--

DROP TABLE IF EXISTS `ratings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ratings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID пользователя',
  `movieId` int NOT NULL COMMENT 'Название фильма',
  `rating` float NOT NULL COMMENT 'Оценка от 0.5 до 5.0',
  `timestamp` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_movie` (`user_id`,`movieId`),
  KEY `idx_user` (`user_id`),
  KEY `idx_movie` (`movieId`),
  CONSTRAINT `movies` FOREIGN KEY (`movieId`) REFERENCES `movies` (`movie_id`),
  CONSTRAINT `user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4603 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Оценки пользователей для фильмов';
/*!40101 SET character_set_client = @saved_cs_client */;

